select jsonb_build_object(
'captured_at',current_timestamp,
'version',current_setting('server_version'),
'schemas',(select jsonb_agg(nspname order by nspname) from pg_namespace where nspname in ('audit','billing','core','gamification','profiles','public','public_content','reporting','security','training')),
'enums',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',t.typname,'labels',(select jsonb_agg(enumlabel order by enumsortorder) from pg_enum where enumtypid=t.oid))) from pg_type t join pg_namespace n on n.oid=t.typnamespace where t.typtype='e' and n.nspname in ('public','core','billing','training','gamification','security','profiles')),
'sequences',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'type',format_type(s.seqtypid,null),'start',s.seqstart,'increment',s.seqincrement,'min',s.seqmin,'max',s.seqmax,'cache',s.seqcache,'cycle',s.seqcycle,'owner_table',cn.nspname||'.'||ct.relname,'owner_column',a.attname)) from pg_sequence s join pg_class c on c.oid=s.seqrelid join pg_namespace n on n.oid=c.relnamespace left join pg_depend d on d.objid=c.oid and d.classid='pg_class'::regclass and d.deptype in ('a','i') left join pg_class ct on ct.oid=d.refobjid left join pg_namespace cn on cn.oid=ct.relnamespace left join pg_attribute a on a.attrelid=ct.oid and a.attnum=d.refobjsubid where n.nspname in ('audit','billing','core','gamification','profiles','public','public_content','reporting','security','training') and coalesce(d.deptype,'')<>'i'),
'tables',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'columns',(select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notnull',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,'default',pg_get_expr(d.adbin,d.adrelid)) order by a.attnum) from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),'constraints',(select jsonb_agg(jsonb_build_object('name',k.conname,'type',k.contype,'definition',pg_get_constraintdef(k.oid))) from pg_constraint k where k.conrelid=c.oid and k.contype<>'n'))) from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relkind in ('r','p') and n.nspname in ('audit','billing','core','gamification','profiles','public','public_content','reporting','security','training')),
'functions',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'identity_args',pg_get_function_identity_arguments(p.oid),'owner',pg_get_userbyid(p.proowner),'definition',pg_get_functiondef(p.oid),'grants',(select jsonb_agg(jsonb_build_object('role',case when x.grantee=0 then 'PUBLIC' else pg_get_userbyid(x.grantee) end,'privilege',x.privilege_type)) from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) x))) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where p.prokind='f' and n.nspname in ('audit','billing','core','gamification','profiles','public','public_content','reporting','security','training') and not exists(select 1 from pg_depend d where d.classid='pg_proc'::regclass and d.objid=p.oid and d.deptype='e')),
'views',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'definition',pg_get_viewdef(c.oid,true),'options',c.reloptions,'dependencies',(select jsonb_agg(distinct jsonb_build_object('schema',vn.nspname,'name',vc.relname)) from pg_rewrite rw join pg_depend d on d.classid='pg_rewrite'::regclass and d.objid=rw.oid join pg_class vc on vc.oid=d.refobjid join pg_namespace vn on vn.oid=vc.relnamespace where rw.ev_class=c.oid and vc.relkind='v' and vc.oid<>c.oid))) from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relkind='v' and n.nspname in ('audit','billing','core','gamification','profiles','public','public_content','reporting','security','training')),
'indexes',(select jsonb_agg(pg_get_indexdef(i.indexrelid)) from pg_index i join pg_class c on c.oid=i.indrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('audit','billing','core','gamification','profiles','public','public_content','reporting','security','training') and not exists(select 1 from pg_constraint k where k.conindid=i.indexrelid)),
'policies',(select jsonb_agg(to_jsonb(p)) from pg_policies p where p.schemaname in ('audit','billing','core','gamification','profiles','public','public_content','reporting','security','training')),
'triggers',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',t.tgname,'definition',pg_get_triggerdef(t.oid))) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where not t.tgisinternal and (n.nspname in ('audit','billing','core','gamification','profiles','public','public_content','reporting','security','training') or (n.nspname='auth' and t.tgname in ('on_auth_user_created','trigger_sync_first_login_on_password_change','trigger_sync_last_login_from_auth')))),
'grants',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'kind',c.relkind,'role',case when x.grantee=0 then 'PUBLIC' else pg_get_userbyid(x.grantee) end,'privilege',x.privilege_type)) from pg_class c join pg_namespace n on n.oid=c.relnamespace cross join lateral aclexplode(c.relacl) x where c.relkind in ('r','p','v','S') and n.nspname in ('audit','billing','core','gamification','profiles','public','public_content','reporting','security','training') and (x.grantee=0 or pg_get_userbyid(x.grantee) in ('anon','authenticated','service_role'))),
'schema_grants',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'role',case when x.grantee=0 then 'PUBLIC' else pg_get_userbyid(x.grantee) end,'privilege',x.privilege_type)) from pg_namespace n cross join lateral aclexplode(n.nspacl) x where n.nspname in ('audit','billing','core','gamification','profiles','public','public_content','reporting','security','training') and (x.grantee=0 or pg_get_userbyid(x.grantee) in ('anon','authenticated','service_role')))
) as snapshot;
